CREATE DATABASE IF NOT EXISTS smart_blood_donor_finder CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_blood_donor_finder;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS verification_codes; DROP TABLE IF EXISTS notifications; DROP TABLE IF EXISTS reviews; DROP TABLE IF EXISTS donations; DROP TABLE IF EXISTS blood_requests; DROP TABLE IF EXISTS donor_profiles; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(user_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,blood_group ENUM('A+','A-','B+','B-','AB+','AB-','O+','O-') NOT NULL,location VARCHAR(160) NOT NULL,role ENUM('patient','donor') NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_search(role,blood_group,location)) ENGINE=InnoDB;
CREATE TABLE donor_profiles(user_id INT UNSIGNED PRIMARY KEY,availability ENUM('Available','Unavailable') NOT NULL DEFAULT 'Available',eligible TINYINT(1) NOT NULL DEFAULT 1,last_donation DATE,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,INDEX(availability,eligible)) ENGINE=InnoDB;
CREATE TABLE blood_requests(request_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id INT UNSIGNED NOT NULL,donor_id INT UNSIGNED NOT NULL,hospital VARCHAR(190) NOT NULL,details TEXT,status ENUM('Pending','Accepted','Rejected','Donation_Marked','Confirmed','Cancelled') NOT NULL DEFAULT 'Pending',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(donor_id) REFERENCES users(user_id) ON DELETE CASCADE,INDEX(patient_id,created_at),INDEX(donor_id,status)) ENGINE=InnoDB;
CREATE TABLE donations(donation_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id INT UNSIGNED NOT NULL UNIQUE,donor_id INT UNSIGNED NOT NULL,patient_id INT UNSIGNED NOT NULL,donation_date DATETIME,status ENUM('Marked','Confirmed') NOT NULL DEFAULT 'Marked',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES blood_requests(request_id) ON DELETE CASCADE,FOREIGN KEY(donor_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(patient_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE reviews(review_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id INT UNSIGNED NOT NULL UNIQUE,patient_id INT UNSIGNED NOT NULL,donor_id INT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment VARCHAR(1000),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_rating CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(request_id) REFERENCES blood_requests(request_id) ON DELETE CASCADE,FOREIGN KEY(patient_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(donor_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notifications(notification_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,message VARCHAR(500) NOT NULL,type VARCHAR(40) DEFAULT 'info',is_read TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,INDEX(user_id,is_read,created_at)) ENGINE=InnoDB;
CREATE TABLE verification_codes(code_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id INT UNSIGNED NOT NULL UNIQUE,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,status ENUM('Active','Used','Expired') DEFAULT 'Active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES blood_requests(request_id) ON DELETE CASCADE,INDEX(status,expires_at)) ENGINE=InnoDB;
